using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using Unity.Profiling;
namespace AstroGateway.CinematicHUD {public class HUDPerformanceProbe:MonoBehaviour {
 public string output;public System.Action finished;IEnumerator Start(){var hud=FindAnyObjectByType<AstroGatewayHUDController>();while(!hud||!hud.safe||!hud.game.initialized)yield return null;hud.game.testing=true;hud.settings.quality=1;hud.environment.ApplyQuality(1);int prior=hud.settings.visibility;var lines=new List<string>{"Actual Unity Editor batch Play Mode. Not physical Android, not UI-only GPU timing, not an improvement claim.","Unity="+Application.unityVersion+" GPU="+SystemInfo.graphicsDeviceName+" API="+SystemInfo.graphicsDeviceType+" framebuffer="+Screen.width+"x"+Screen.height,"Medium graphics; fixed astronaut spawn; clear weather. 2s warmup + >=4s per profile; no screenshots or deliberate sleeps during samples."};using(var cpu=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread",1))using(var gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame",1)){foreach(int mode in new[]{0,1,3}){hud.settings.visibility=mode;hud.ApplySettings();yield return new WaitForSecondsRealtime(2);double start=Time.realtimeSinceStartupAsDouble,prev=start;var times=new List<double>();var cpus=new List<double>();var gcs=new List<double>();while(Time.realtimeSinceStartupAsDouble-start<4){yield return null;double now=Time.realtimeSinceStartupAsDouble;times.Add((now-prev)*1000);prev=now;if(cpu.Valid&&cpu.LastValue>0)cpus.Add(cpu.LastValue/1000000d);if(gc.Valid)gcs.Add(gc.LastValue);}times.Sort();lines.Add(new[]{"Full","Compact","Minimal","Hidden"}[mode]+": frames="+times.Count+" max_ms="+times.Max().ToString("F2")+" sample_valid="+(times.Max()<2000)+" mean_ms="+times.Average().ToString("F2")+" effective_fps="+(1000/times.Average()).ToString("F2")+" p95_ms="+times[Math.Min(times.Count-1,(int)(times.Count*.95))].ToString("F2")+" MainThread_recorder_ms="+(cpus.Count>0?cpus.Average().ToString("F3"):"unavailable")+" GC_recorder_bytes_per_frame="+(gcs.Count>0?gcs.Average().ToString("F1"):"unavailable")+" active_graphics="+hud.GetComponentsInChildren<UnityEngine.UI.Graphic>().Length+" actual_profile_index="+hud.settings.visibility+" active_cards="+string.Join(",",hud.safe.Cast<Transform>().Where(t=>t.gameObject.activeInHierarchy).Select(t=>t.name)));}}
 lines.Add("Unity reported total allocated bytes="+UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()+" (Editor process scope; not Android RSS or UI-only memory)");lines.Add("GPU timing and physical-device thermal behavior not measured. Short capped Editor samples are not proof of Android readiness.");File.WriteAllLines(output,lines);hud.settings.visibility=prior;hud.ApplySettings();
#if UNITY_EDITOR
 if(finished!=null)finished();else UnityEditor.EditorApplication.Exit(0);
#endif
}}}
